        r.mu.Lock()
        defer r.mu.Unlock()

        if _, exists := r.models[name]; !exists {
                return fmt.Errorf("model %q not found", name)
        }

        delete(r.models, name)
        filename := filepath.Join(r.dataDir, name+".json")
        os.Remove(filename)
        return nil
}

