// findVersionLocked returns the version pointer for the given model and version number.
// The caller must hold an appropriate lock.
func (r *Registry) findVersionLocked(modelName string, versionNum int) (*Model, *Version, error) {
	model, exists := r.models[modelName]
	if !exists {
		return nil, nil, fmt.Errorf("model %q not found", modelName)
	}

	for _, v := range model.Versions {
		if v.Number == versionNum {
			return model, v, nil
		}
	}
	return nil, nil, fmt.Errorf("version %d not found for model %q", versionNum, modelName)
}

// validateAnnotationKey returns true if key is non-empty and contains only
// letters, digits, and underscores.
func validateAnnotationKey(key string) bool {
	return annotationKeyRegexp.MatchString(key)
}

// AddAnnotation attaches a new key-value annotation to a model version.
func (r *Registry) AddAnnotation(modelName string, versionNum int, key, value string) (*Annotation, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	if _, _, err := r.findVersionLocked(modelName, versionNum); err != nil {
		return nil, err
	}
	if !validateAnnotationKey(key) {
		return nil, fmt.Errorf("invalid annotation key")
	}

	if r.annotations[modelName] == nil {
		r.annotations[modelName] = make(map[int]map[string]*Annotation)
	}
	if r.annotations[modelName][versionNum] == nil {
		r.annotations[modelName][versionNum] = make(map[string]*Annotation)
	}
	if _, exists := r.annotations[modelName][versionNum][key]; exists {
		return nil, fmt.Errorf("annotation %q already exists", key)
	}

	annotation := &Annotation{
		Key:       key,
		Value:     value,
		CreatedAt: time.Now(),
	}
	r.annotations[modelName][versionNum][key] = annotation
	return annotation, nil
}

// ListAnnotations returns all annotations for a model version sorted by key.
func (r *Registry) ListAnnotations(modelName string, versionNum int) ([]*Annotation, error) {
	r.mu.RLock()
	defer r.mu.RUnlock()

	if _, _, err := r.findVersionLocked(modelName, versionNum); err != nil {
		return nil, err
	}

	var annotations []*Annotation
	if versions, ok := r.annotations[modelName]; ok {
		if keys, ok := versions[versionNum]; ok {
			for _, a := range keys {
				annotations = append(annotations, a)
			}
		}
	}
	sort.Slice(annotations, func(i, j int) bool {
		return annotations[i].Key < annotations[j].Key
	})
	if annotations == nil {
		annotations = []*Annotation{}
	}
	return annotations, nil
}

// DeleteAnnotation removes a specific annotation from a model version.
func (r *Registry) DeleteAnnotation(modelName string, versionNum int, key string) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	if _, _, err := r.findVersionLocked(modelName, versionNum); err != nil {
		return err
	}

	if r.annotations[modelName] == nil || r.annotations[modelName][versionNum] == nil {
		return fmt.Errorf("annotation %q not found", key)
	}
	if _, exists := r.annotations[modelName][versionNum][key]; !exists {
		return fmt.Errorf("annotation %q not found", key)
	}
	delete(r.annotations[modelName][versionNum], key)
	return nil
}

// AnnotationsMap returns a map of annotation key to value for a model version.
func (r *Registry) AnnotationsMap(modelName string, versionNum int) map[string]string {
	r.mu.RLock()
	defer r.mu.RUnlock()

	result := make(map[string]string)
	if versions, ok := r.annotations[modelName]; ok {
		if keys, ok := versions[versionNum]; ok {
			for k, a := range keys {
				result[k] = a.Value
			}
		}
	}
	return result
}
