// RecordRequest updates serving statistics for a single inference request.
func (s *Server) RecordRequest(modelName string, successful bool, latencyMs float64) {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.stats.TotalRequests++
	if successful {
		s.stats.Successful++
		s.stats.LatencySum += latencyMs
	} else {
		s.stats.Failed++
	}

	model := s.stats.Models[modelName]
	if model == nil {
		model = &ModelStats{}
		s.stats.Models[modelName] = model
	}
	model.Requests++
	if successful {
		model.Successful++
		model.LatencySum += latencyMs
	} else {
		model.Failed++
	}
}

// GetStats returns a snapshot of accumulated serving statistics.
func (s *Server) GetStats() StatsResponse {
	s.mu.RLock()
	defer s.mu.RUnlock()

	resp := StatsResponse{
		TotalRequests: s.stats.TotalRequests,
		Successful:    s.stats.Successful,
		Failed:        s.stats.Failed,
		Models:        make(map[string]ModelStatsResponse),
	}
	if s.stats.Successful > 0 {
		resp.AvgLatencyMs = s.stats.LatencySum / float64(s.stats.Successful)
	}

	for name, model := range s.stats.Models {
		m := ModelStatsResponse{
			Requests:   model.Requests,
			Successful: model.Successful,
			Failed:     model.Failed,
		}
		if model.Successful > 0 {
			m.AvgLatencyMs = model.LatencySum / float64(model.Successful)
		}
		resp.Models[name] = m
	}
	return resp
}

// ResetStats resets all serving statistics to zero.
func (s *Server) ResetStats() {
	s.mu.Lock()
	defer s.mu.Unlock()

	s.stats = Stats{
		Models: make(map[string]*ModelStats),
	}
}
