			result.Errors = append(result.Errors, fmt.Sprintf("unknown step type: %s", step.Type))
		}
		for _, dep := range step.Dependencies {
			if !seen[dep] {
				result.Valid = false
			result.Errors = append(result.Errors, fmt.Sprintf("step %s depends on unknown step: %s", step.Name, dep))
			}
		}
	}

	ordered, err := topologicalSort(p.Steps)
	if err != nil {
		result.Valid = false
		result.Errors = append(result.Errors, "dependency cycle detected")
	}

	if result.Valid && err == nil {
		for _, step := range ordered {
			result.ExecutionOrder = append(result.ExecutionOrder, step.Name)
		}
	}

	if len(result.Errors) > 0 {
		result.Valid = false
		result.ExecutionOrder = []string{}
	}

	return result
}
